import pandas as pd
import pdfplumber
import json
import re
from difflib import get_close_matches

def normalize(text):
    return str(text).strip()

try:
    # Load Data
    print("Loading data...")
    df_vendors = pd.read_excel('/root/vendors.xlsx')
    df_pos = pd.read_csv('/root/purchase_orders.csv')

    # Prepare Vendor Data
    vendors_map = {}
    vendor_names = []
    for _, row in df_vendors.iterrows():
        name = normalize(row['name'])
        vendors_map[name] = {
            'id': normalize(row['id']),
            'iban': normalize(row['iban'])
        }
        vendor_names.append(name)

    # Prepare PO Data
    pos_map = {}
    for _, row in df_pos.iterrows():
        po_num = normalize(row['po_number'])
        pos_map[po_num] = {
            'vendor_id': normalize(row['vendor_id']),
            'amount': float(row['amount'])
        }

    findings = []

    print("Processing PDF...")
    with pdfplumber.open('/root/invoices.pdf') as pdf:
        for i, page in enumerate(pdf.pages):
            page_num = i + 1
            text = page.extract_text()
            if not text:
                continue

            vendor_name = None
            amount = 0.0
            iban = None
            po_number = None

            lines = text.split('\n')
            for line in lines:
                line = line.strip()
                if line.startswith("From:"):
                    vendor_name = line[5:].strip()
                elif line.startswith("Total"):
                    m = re.search(r'\$\s*([\d\.]+)', line)
                    if m:
                        amount = float(m.group(1))
                elif line.startswith("Payment IBAN:"):
                    iban = line[13:].strip()
                elif line.startswith("PO Number:"):
                    po_val = line[10:].strip()
                    if po_val and po_val.lower() != "null":
                        po_number = po_val

            reason = None
            matched_vendor_entry = None

            # 1. Unknown Vendor
            if vendor_name in vendors_map:
                matched_vendor_entry = vendors_map[vendor_name]
            else:
                # Fuzzy match with 0.8 cutoff
                matches = get_close_matches(vendor_name, vendor_names, n=1, cutoff=0.8)
                if matches:
                    matched_vendor_entry = vendors_map[matches[0]]
                else:
                    reason = "Unknown Vendor"

            if not reason:
                vendor_id = matched_vendor_entry['id']
                auth_iban = matched_vendor_entry['iban']

                # 2. IBAN Mismatch
                if iban != auth_iban:
                    reason = "IBAN Mismatch"

                # 3. Invalid PO
                elif po_number is None or po_number not in pos_map:
                    reason = "Invalid PO"

                else:
                    po_data = pos_map[po_number]

                    # 4. Amount Mismatch
                    if abs(amount - po_data['amount']) > 0.01:
                        reason = "Amount Mismatch"

                    # 5. Vendor Mismatch
                    elif po_data['vendor_id'] != vendor_id:
                        reason = "Vendor Mismatch"

            if reason:
                findings.append({
                    "invoice_page_number": page_num,
                    "vendor_name": vendor_name,
                    "invoice_amount": amount,
                    "iban": iban,
                    "po_number": po_number,
                    "reason": reason
                })

    print(f"Found {len(findings)} fraudulent invoices.")
    with open('/root/fraud_report.json', 'w') as f:
        json.dump(findings, f, indent=2)

except Exception as e:
    print(f"Error: {e}")
EOF
